import React, { useState, useEffect, useReducer } from 'react';
import DataSet from './components/DataSet';
import './App.css';
import commentsData from './data/comments.json'; // Импортируем локальные данные

const initialState = {
  comments: [],
  loading: true,
  error: null,
};

function dataReducer(state, action) {
  switch (action.type) {
    case 'SET_COMMENTS':
      return { ...state, comments: action.payload, loading: false };
    case 'ADD_COMMENT':
      return { ...state, comments: [...state.comments, action.payload] };
    case 'UPDATE_COMMENT':
      return {
        ...state,
        comments: state.comments.map((comment) =>
          comment.id === action.payload.id ? action.payload : comment
        ),
      };
    case 'DELETE_COMMENTS':
      return {
        ...state,
        comments: state.comments.filter(
          (comment) => !action.payload.includes(comment.id)
        ),
      };
    case 'SET_ERROR':
      return { ...state, error: action.payload, loading: false };
    default:
      return state;
  }
}

function App() {
  const [state, dispatch] = useReducer(dataReducer, initialState);

  // Загрузка данных из локального JSON
  useEffect(() => {
    dispatch({ type: 'SET_COMMENTS', payload: commentsData });
  }, []);

  // Остальной код остаётся без изменений
  const handleAddComment = (newComment) => {
    const lastId = state.comments.reduce((max, comment) => Math.max(max, comment.id), 0);
    const optimisticComment = { ...newComment, id: lastId + 1 };
    dispatch({ type: 'ADD_COMMENT', payload: optimisticComment });
  };

  const handleUpdateComment = (updatedComment) => {
    dispatch({ type: 'UPDATE_COMMENT', payload: updatedComment });
  };

  const handleDeleteComments = (selectedIds) => {
    dispatch({ type: 'DELETE_COMMENTS', payload: selectedIds });
  };

  const headers = [
    { property: 'id', label: 'ID' },
    { property: 'name', label: 'Имя' },
    { property: 'email', label: 'Email' },
    { property: 'body', label: 'Комментарий' },
  ];

  return (
    <div className="App">
      <h1>Таблица комментариев</h1>
      {state.loading ? (
        <p>Загрузка данных...</p>
      ) : state.error ? (
        <p>{state.error}</p>
      ) : (
        <DataSet
          headers={headers}
          data={state.comments}
          onAdd={(newComment) => handleAddComment(newComment)}
          onDelete={(selectedIds) => handleDeleteComments(selectedIds)}
          onUpdate={(updatedComment) => handleUpdateComment(updatedComment)}
        />
      )}
    </div>
  );
}

export default App;
